SELECT d.d_year, i.i_category, p.p_promo_name, SUM(s.ext_sales_price) AS total_sales, COUNT(DISTINCT s.ticket_number) AS order_count FROM (SELECT ss_sold_date_sk AS sold_date_sk, ss_item_sk AS item_sk, ss_promo_sk AS promo_sk, ss_ext_sales_price AS ext_sales_price, ss_ticket_number AS ticket_number, ss_quantity FROM store_sales WHERE ss_quantity > 66) s JOIN date_dim d ON s.sold_date_sk = d.d_date_sk JOIN item i ON s.item_sk = i.i_item_sk JOIN promotion p ON s.promo_sk = p.p_promo_sk WHERE d.d_year = 1908 GROUP BY d.d_year, i.i_category, p.p_promo_name HAVING COUNT(DISTINCT s.ticket_number) > 317818
